import { useState } from 'react';

function AddLessonForm() {
 const [form, setForm] = useState({
 title: "",
 learn: "",
 summary: "",
 status: "locked"
 });

 function handleChange(e) {
 const { name, value } = e.target; // name = input's name attribute, value = typed value
 setForm({
...form, // Keep other fields
 [name]: value // Update only changed field - dynamic key
 });
 }

 return (
 <div style={{display: 'grid', gap: '10px', maxWidth: '400px'}}>
 <input name="title" value={form.title} onChange={handleChange} placeholder="Lesson Title" />
 <input name="learn" value={form.learn} onChange={handleChange} placeholder="What you will learn" />
 <input name="summary" value={form.summary} onChange={handleChange} placeholder="Summary" />
 <select name="status" value={form.status} onChange={handleChange}>
 <option value="locked">Locked</option>
 <option value="current">Current</option>
 <option value="completed">Completed</option>
 </select>
 <p>Preview: {form.title} - {form.status}</p>
 </div>
 );
}
// One handleChange for all inputs! Uses name attribute to know which field changed

import { useState } from 'react';

function AddLesson() {
 const [lessons, setLessons] = useState([]);
 const [form, setForm] = useState({ title: "", learn: "" });

 function handleChange(e) {
 setForm({...form, [e.target.name]: e.target.value});
 }

 function handleSubmit(e) {
 e.preventDefault(); // STOP page reload - MOST IMPORTANT LINE!
 if (!form.title.trim()) {
 alert("Title required!");
 return;
 }
 const newLesson = {
 id: lessons.length + 1,
 title: form.title,
 learn: form.learn,
 status: "locked"
 };
 setLessons([...lessons, newLesson]); // Add to list
 setForm({ title: "", learn: "" }); // Clear form
 alert("Lesson added!");
 }

 return (
 <div>
 <form onSubmit={handleSubmit}>
 <input name="title" value={form.title} onChange={handleChange} placeholder="Title" required />
 <input name="learn" value={form.learn} onChange={handleChange} placeholder="Learn" />
 <button type="submit">Add Lesson</button>
 </form>
 <ul>{lessons.map(l => <li key={l.id}>{l.title}</li>)}</ul>
 </div>
 );
}
// Without e.preventDefault(), page would reload and lessons state lost!

import { useState } from 'react';

function LessonFormWithValidation() {
 const [form, setForm] = useState({ title: "", email: "" });
 const [errors, setErrors] = useState({});

 function validate() {
 const newErrors = {};
 if (!form.title.trim()) newErrors.title = "Title is required";
 else if (form.title.length < 5) newErrors.title = "Title must be at least 5 characters";
 if (!form.email.includes("@")) newErrors.email = "Valid email required";
 setErrors(newErrors);
 return Object.keys(newErrors).length === 0; // Valid if no errors
 }

 function handleSubmit(e) {
 e.preventDefault();
 if (validate()) {
 alert("Form valid! Submitting: " + form.title);
 // Submit to Firebase here
 }
 }

 return (
 <form onSubmit={handleSubmit} style={{display: 'grid', gap: '8px', maxWidth: '400px'}}>
 <input name="title" value={form.title} onChange={(e) => setForm({...form, title: e.target.value})} placeholder="Title" style={{border: errors.title? '1px solid red' : '1px solid gray'}} />
 {errors.title && <span style={{color: 'red', fontSize: '12px'}}>{errors.title}</span>}

 <input name="email" value={form.email} onChange={(e) => setForm({...form, email: e.target.value})} placeholder="Email" style={{border: errors.email? '1px solid red' : '1px solid gray'}} />
 {errors.email && <span style={{color: 'red', fontSize: '12px'}}>{errors.email}</span>}

 <button type="submit">Submit Lesson</button>
 </form>
 );
}
// Type 'ab' in title -> error "must be at least 5 chars" shows instantly
