import { useState } from 'react';

function Filters() {
 const [filters, setFilters] = useState({
 status: "all",
 showCompleted: true,
 difficulty: "beginner"
 });

 function handleChange(e) {
 const { name, value, type, checked } = e.target;
 setFilters({
...filters,
 [name]: type === 'checkbox'? checked : value // Checkbox uses checked, others use value
 });
 }

 return (
 <div style={{display: 'grid', gap: '10px'}}>
 <select name="status" value={filters.status} onChange={handleChange}>
 <option value="all">All Lessons</option>
 <option value="completed">Completed Only</option>
 <option value="current">Current Only</option>
 </select>

 <label><input type="checkbox" name="showCompleted" checked={filters.showCompleted} onChange={handleChange} /> Show Completed</label>

 <div>
 <label><input type="radio" name="difficulty" value="beginner" checked={filters.difficulty==='beginner'} onChange={handleChange} /> Beginner</label>
 <label><input type="radio" name="difficulty" value="advanced" checked={filters.difficulty==='advanced'} onChange={handleChange} /> Advanced</label>
 </div>

 <p>Filters: {JSON.stringify(filters)}</p>
 </div>
 );
}
// Select uses value, Checkbox uses checked, Radio uses checked comparison
// One handleChange handles all types with type check!

import { useState } from 'react';

function EventDemo() {
 const [text, setText] = useState("");
 const [lessons, setLessons] = useState(["Intro"]);

 function handleKeyPress(e) {
 if (e.key === 'Enter' && text.trim()) {
 setLessons([...lessons, text]);
 setText("");
 }
 }

 function handleClickLesson(id) {
 console.log("Clicked lesson", id);
 alert(`Opening lesson ${id}`);
 }

 return (
 <div>
 <input 
 value={text}
 onChange={(e) => setText(e.target.value)}
 onKeyPress={handleKeyPress} // Press Enter to add
 placeholder="Type lesson and press Enter"
 />
 <p>Press Enter to add, Click lesson to open</p>
 {lessons.map((lesson, i) => (
 <div key={i} onClick={() => handleClickLesson(i)} style={{padding: '8px', border: '1px solid gray', margin: '5px', cursor: 'pointer'}}>
 {lesson}
 </div>
 ))}
 </div>
 );
}
// onChange for typing, onKeyPress for Enter key, onClick for clicking lesson card
// These 3 events power 90% of your dashboard interactions!

import { useState } from 'react';

function LessonSearch() {
 const [search, setSearch] = useState("");
 const [filter, setFilter] = useState("all");
 const lessons = [
 {id: 1, title: "Introduction to React", status: "completed"},
 {id: 2, title: "JSX and Components", status: "current"},
 {id: 3, title: "Props and Communication", status: "locked"},
 {id: 4, title: "React Hooks Deep Dive", status: "locked"},
 ];

 const filtered = lessons.filter(lesson => {
 const matchesSearch = lesson.title.toLowerCase().includes(search.toLowerCase());
 const matchesFilter = filter === "all" || lesson.status === filter;
 return matchesSearch && matchesFilter;
 });

 return (
 <div>
 <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search..." style={{padding: '8px', width: '200px'}} />
 <select value={filter} onChange={(e) => setFilter(e.target.value)} style={{padding: '8px', marginLeft: '10px'}}>
 <option value="all">All</option>
 <option value="completed">Completed</option>
 <option value="current">Current</option>
 <option value="locked">Locked</option>
 </select>
 <p>Showing {filtered.length} of {lessons.length} lessons</p>
 {filtered.map(l => <p key={l.id}>{l.title} - {l.status}</p>)}
 </div>
 );
}
