import { useState } from 'react';

function App() {
 const [lessons, setLessons] = useState([
 {id: 1, title: "Introduction to React", learn: "What is React", status: "completed"},
 {id: 2, title: "JSX and Components", learn: "Build components", status: "current"},
 ]);
 const [form, setForm] = useState({ title: "", learn: "", status: "locked" });
 const [search, setSearch] = useState("");
 const [errors, setErrors] = useState({});
 const [showForm, setShowForm] = useState(false);

 function handleFormChange(e) {
 setForm({...form, [e.target.name]: e.target.value});
 if (errors[e.target.name]) setErrors({...errors, [e.target.name]: ""}); // Clear error on typing
 }

 function validate() {
 const newErrors = {};
 if (!form.title.trim()) newErrors.title = "Title required";
 else if (form.title.length < 5) newErrors.title = "Min 5 chars";
 if (!form.learn.trim()) newErrors.learn = "Learn field required";
 setErrors(newErrors);
 return Object.keys(newErrors).length === 0;
 }

 function handleSubmit(e) {
 e.preventDefault();
 if (!validate()) return;
 const newLesson = { id: lessons.length + 1,...form };
 setLessons([...lessons, newLesson]);
 setForm({ title: "", learn: "", status: "locked" });
 setShowForm(false);
 }

 const filtered = lessons.filter(l => l.title.toLowerCase().includes(search.toLowerCase()));

 return (
 <div style={{background: '#07111f', color: 'white', minHeight: '100vh', padding: '20px'}}>
 <div style={{display: 'flex', gap: '10px', marginBottom: '20px'}}>
 <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search lessons..." style={{padding: '10px', flex: 1}} />
 <button onClick={() => setShowForm(!showForm)} style={{padding: '10px 15px', background: '#61dafb', border: 'none', borderRadius: '8px', fontWeight: '800'}}>{showForm? "Cancel" : "+ Add Lesson"}</button>
 </div>

 {showForm && (
 <form onSubmit={handleSubmit} style={{background: 'rgba(15,31,51,0.88)', padding: '20px', borderRadius: '16px', display: 'grid', gap: '10px', marginBottom: '20px'}}>
 <input name="title" value={form.title} onChange={handleFormChange} placeholder="Lesson Title (min 5 chars)" style={{padding: '10px', border: errors.title? '1px solid red' : '1px solid #1e293b', borderRadius: '8px'}} />
 {errors.title && <span style={{color: '#ef4444', fontSize: '12px'}}>{errors.title}</span>}
 <input name="learn" value={form.learn} onChange={handleFormChange} placeholder="What you will learn" style={{padding: '10px', border: errors.learn? '1px solid red' : '1px solid #1e293b', borderRadius: '8px'}} />
 {errors.learn && <span style={{color: '#ef4444', fontSize: '12px'}}>{errors.learn}</span>}
 <select name="status" value={form.status} onChange={handleFormChange} style={{padding: '10px', borderRadius: '8px'}}>
 <option value="locked">Locked</option><option value="current">Current</option><option value="completed">Completed</option>
 </select>
 <button type="submit" style={{padding: '12px', background: 'linear-gradient(135deg, #61dafb, #0ea5e9)', border: 'none', borderRadius: '8px', fontWeight: '800'}}>Create Lesson</button>
 </form>
 )}

 <p style={{color: '#94a3b8'}}>Showing {filtered.length} lessons</p>
 <div style={{display: 'grid', gap: '12px', marginTop: '15px'}}>
 {filtered.map(l => (
 <div key={l.id} style={{border: '1px solid rgba(97,218,251,0.16)', padding: '15px', borderRadius: '12px'}}>
 <h4>{l.title} - {l.status}</h4><p style={{color: '#94a3b8', fontSize: '13px'}}>{l.learn}</p>
 </div>
 ))}
 </div>
 </div>
 );
}
export default App;
